package com.steadyme.app.ui;
import android.os.Bundle;import android.view.*;import com.google.android.material.snackbar.Snackbar;import androidx.annotation.*;import androidx.fragment.app.Fragment;import com.steadyme.app.data.FirebaseRepository;import com.steadyme.app.databinding.FragmentManualLogBinding;import com.steadyme.app.model.MoodLog;
public class ManualLogFragment extends Fragment{private FragmentManualLogBinding binding;private String emotion;@Nullable @Override public View onCreateView(@NonNull LayoutInflater i,@Nullable ViewGroup c,@Nullable Bundle s){binding=FragmentManualLogBinding.inflate(i,c,false);return binding.getRoot();}@Override public void onViewCreated(@NonNull View v,@Nullable Bundle s){binding.btnHappy.setOnClickListener(x->pick("Happy",8));binding.btnCalm.setOnClickListener(x->pick("Calm",7));binding.btnElated.setOnClickListener(x->pick("Elated",10));binding.btnAnxious.setOnClickListener(x->pick("Anxious",3));binding.btnSad.setOnClickListener(x->pick("Sad",2));binding.btnTired.setOnClickListener(x->pick("Tired",4));binding.btnAngry.setOnClickListener(x->pick("Angry",2));binding.btnOverwhelmed.setOnClickListener(x->pick("Overwhelmed",3));binding.btnSaveMood.setOnClickListener(x->save());}@Override public void onDestroyView(){binding=null;super.onDestroyView();}
 private int score;private void pick(String value,int valueScore){emotion=value;score=valueScore;binding.tvSelectedEmotion.setText(value+" selected");binding.btnSaveMood.setEnabled(true);}private void save(){if(emotion==null){Snackbar.make(binding.getRoot(),"Select an emotion first",Snackbar.LENGTH_SHORT).show();return;}new FirebaseRepository().saveMood(new MoodLog(emotion,String.valueOf(binding.etNotes.getText()).trim(),"manual",score),new FirebaseRepository.SaveCallback(){public void onSaved(){Snackbar.make(binding.getRoot(),"Mood saved",Snackbar.LENGTH_SHORT).show();getParentFragmentManager().popBackStack();}public void onError(Exception e){Snackbar.make(binding.getRoot(),e.getMessage(),Snackbar.LENGTH_LONG).show();}});}}
